/**
 * @param {number[]} nums
 * @param {number} x
 * @param {number} k
 * @return {number}
 */
var minOperations = function(nums, x, k) {
    const n = nums.length;
    const dp = Array(n - x).fill(0);

    for (let i = x; i <= n; i++) {
        const arr = nums.slice(i - x, i).sort((a, b) => a - b);
        const halfLen = Math.floor(x / 2);
        const median = x & 1 ? arr[halfLen] : Math.floor((arr[halfLen - 1] + arr[halfLen]) / 2);
        const diff = arr.reduce((acc, el) => acc + Math.abs(el - median), 0);
        dp[i - x] = diff;
    }

    const memo = Array.from({ length: dp.length }, () => Array(k + 1));

    const grab = (pos, missing) => {
        if (memo[pos][missing] !== undefined) return memo[pos][missing];
        if (pos >= dp.length) return Infinity;
        if (missing === 1) return dp[pos];

        let min = Infinity;

        for (let i = pos + x; i < dp.length; i++) {
            min = Math.min(min, grab(i, missing - 1));
        }

        memo[pos][missing] = dp[pos] + min;
        return memo[pos][missing];
    };

    let res = Infinity;

    for (let i = 0; i <= dp.length - k; i++) {
        res = Math.min(res, grab(i, k));
    }

    return res;
};

/**
 * @param {number[]} nums
 * @param {number} x
 * @param {number} k
 * @return {number}
 */
var minOperations = function(nums, x, k) {
    const n = nums.length;
    const dp = Array(n - x + 1).fill(0);
    const halfLen = Math.floor(x / 2);

    for (let i = 0; i <= n - x; i++) {
        const arr = nums.slice(i, i + x).sort((a, b) => a - b);

        for (const num of arr) {
            dp[i] += Math.abs(num - arr[halfLen]);
        }
    }

    let prev = Array(dp.length + 1).fill(Infinity);

    for (let missing = 1; missing <= k; missing++) {
        const curr = Array(dp.length + 1).fill(Infinity);

        for (let pos = dp.length - 1; pos >= 0; pos--) {
            const take = missing === 1
                ? dp[pos]
                : dp[pos] + (prev[pos + x] ?? Infinity);

            curr[pos] = Math.min(curr[pos + 1], take);
        }

        prev = curr;
    }

    return prev[0];
};

